    #[test]
    fn halt_traps_disarmed_on_mainnet_net0() {
        let _env = crate::test_env::guard();
        // §12 (mainnet-hard-off needs a network_id==0 context test): exercise the net-0 branch of
        // the halt-trap disarm directly. Pre-fix, the connect_block guards `fraud_proof_enforced`
        // (chain.rs:~1058) and `pool_admission_enforced` (chain.rs:~4753) were ON on mainnet —
        // fraud >= 50,000, pool-admission >= 61,414 — while their validators are HARD-OFF
        // (`verify_fraud_proof` -> "fraud proof: mainnet hard-off", poawx_challenge.rs:194; the
        // 7-arg `TicketProof::validate` -> "ticket proof: mainnet hard-off", poawx_ticket.rs:522 —
        // both separately tested). So the FIRST block carrying a fraud-proof section or a non-winner
        // (multi-payee fan-out) pool member would reach a hard-off validator -> reject -> chain HALT
        // (the enforce-ON / validate-OFF class that halted mainnet 2026-07-23). This pins BOTH
        // guards OFF on net-0 at and beyond their activation heights, so connect_block never reaches
        // the hard-off validators. A green devnet/testnet suite (network_id != 0) does NOT cover
        // this branch — hence the explicit net-0 context here.
        let _g = chain_poawx_env_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        std::env::set_var("IRIUM_NETWORK", "mainnet");
        assert_eq!(
            crate::activation::network_id_byte(),
            0,
            "net-0 (mainnet) context required to exercise the hard-off branch"
        );

        let poawx = crate::activation::MAINNET_POAWX_ACTIVATION_HEIGHT.expect("poawx activation set");
        let combined =
            crate::activation::MAINNET_COMBINED_ACTIVATION_HEIGHT.expect("combined activation set");
        let past = combined + 10_000; // well past both activations (mirrors the live tip)

        // Control: both activations ARE reached at these heights — pre-fix, that is exactly what
        // armed the gates to true, so a false result here is the disarm doing real work.
        assert!(past >= poawx && past >= combined && combined >= poawx);

        // Fraud halt-trap DISARMED: connect_block guard OFF at and beyond the poawx activation.
        assert!(
            !crate::poawx_challenge::fraud_proof_enforced(poawx),
            "fraud enforcement must be OFF on mainnet at the activation height (halt-trap disarmed)"
        );
        assert!(
            !crate::poawx_challenge::fraud_proof_enforced(past),
            "fraud enforcement must be OFF on mainnet past the activation height"
        );

        // Pool/ticket halt-trap RESOLVED BY COUPLING (not by staying off): OFF below the
        // fair-distribution activation (no enforce-on/validate-off trap can fire in the
        // pre-activation window), and ARMED at/after it — but armed TOGETHER with the
        // now-un-hard-off ticket validator (poawx_ticket.rs), so it can never be
        // enforce-on/validate-off. (`past` well beyond fd is therefore enforced, not off.)
        let fd = crate::activation::MAINNET_FAIR_DISTRIBUTION_ACTIVATION_HEIGHT
            .expect("fair-distribution activated");
        assert!(
            !pool_admission_enforced(combined),
            "pool-admission OFF at the combined activation (below the fair-distribution activation)"
        );
        assert!(
            !pool_admission_enforced(fd - 1),
            "pool-admission OFF just below the fair-distribution activation"
        );
        assert!(
            pool_admission_enforced(fd) && pool_admission_enforced(past),
            "pool-admission ARMED at/after the fair-distribution activation (coupled with its validator)"
        );

        std::env::remove_var("IRIUM_NETWORK");
    }

    #[test]
    fn mandatory_inclusion_disarmed_on_mainnet_net0() {
        let _env = crate::test_env::guard();
        // §12 again: mandatory-inclusion ENFORCE used to ride `pool_ticket_enforced`, so it armed on
        // mainnet at the combined fair-distribution activation (62,236) with NO producer-side
        // support — `canonical_eligible_set`/`scan_block_registrations` have no caller outside the
        // validator. Worse, the rule is jointly UNSATISFIABLE with `best_for_role`: an RCR1
        // registration carries a RoleCandidate but none of the claim/ticket/puzzle artifacts needed
        // to PAY that role, so a high-weight registration must be included and then becomes
        // best_for_role, which the producer cannot pay. Include -> rejected by best_for_role; omit
        // -> rejected by mandatory-inclusion. Either way the chain halts.
        //
        // It never fired only because PoAW-X blocks are coinbase-only, so no RCR1 can reach the
        // chain. This pins the disarm, and pins that the SIBLING gates stay armed (the disarm must
        // decouple inclusion only, not weaken sybil-cost).
        let _g = chain_poawx_env_lock()
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        std::env::set_var("IRIUM_NETWORK", "mainnet");
        assert_eq!(
            crate::activation::network_id_byte(),
            0,
            "net-0 (mainnet) context required to exercise the mainnet branch"
        );

        let fair = crate::activation::MAINNET_FAIR_DISTRIBUTION_ACTIVATION_HEIGHT
            .expect("fair-distribution activation set");
        let past = fair + 10_000; // mirrors the live tip being well past the activation

        // Control: the coupling source IS live at these heights — pre-fix that is precisely what
        // armed inclusion, so a false result below is the disarm doing real work.
        assert!(
            crate::poawx_ticket::pool_ticket_enforced(fair)
                && crate::poawx_ticket::pool_ticket_enforced(past),
            "control: the gate inclusion used to ride must be ARMED here, else this test proves nothing"
        );

        // DISARMED at and beyond the activation that used to arm it.
        assert!(
            !crate::poawx_admission::mandatory_inclusion_enforce_active(fair),
            "mandatory-inclusion must be OFF on mainnet at the fair-distribution activation"
        );
        assert!(
            !crate::poawx_admission::mandatory_inclusion_enforce_active(past),
            "mandatory-inclusion must be OFF on mainnet well past the activation"
        );

        // Guard against re-arming by flipping the dedicated const without building the producer
        // side: this is the knob that must stay None until that work lands.
        assert!(
            crate::poawx_admission::MAINNET_MANDATORY_INCLUSION_ACTIVATION_HEIGHT.is_none(),
            "re-arming inclusion needs a producer-side implementation AND a fix for the \
             unpayable-candidate/best_for_role conflict, proven on a net-0 connect_block harness"
        );

        // The sibling gates must NOT have been weakened by the decoupling.
        assert!(
            crate::poawx_ticket::tickets_enforced(past),
            "tickets must stay ARMED — the disarm decouples inclusion only"
        );
        assert!(
            pool_admission_enforced(past),
            "pool-admission must stay ARMED — the disarm decouples inclusion only"
        );

        std::env::remove_var("IRIUM_NETWORK");
    }

