    #[test]
    fn non_selected_proposer_rejected_even_with_max_pow() {
        let _env = crate::test_env::guard();
        // The proposer gate rejects a non-selected proposer no matter the PoW: the SAME
        // block is rejected when the eligible set is large (priority misses the round-0
        // cut) and accepted when it is the sole eligible winner. Hashrate never changes
        // the verdict.
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        std::env::set_var("IRIUM_NETWORK", "devnet");
        std::env::set_var("IRIUM_POAWX_PROPOSER_FREEZE_DEPTH", "2");
        let net = crate::activation::network_id_byte();
        let height = 2u64;
        let prev_hash = [0x55u8; 32];
        let seed = expected_epoch_seed(height, prev_hash, None);
        let n_big = 100u64;
        let tau0 = proposer_threshold(n_big, 0);
        let mut k = 0u64;
        let secret = loop {
            let pr = prove(&secret_n(k + 1), net, height, seed);
            if proposer_priority(&pr.vrf_output) >= tau0 {
                break secret_n(k + 1);
            }
            k += 1;
            assert!(k < 10_000);
        };
        let proof = prove(&secret, net, height, seed);
        let vrf_key = proof.assignment_public_key;
        let miner_pkh = proof.solver_pkh;
        let tmpl = ext_skeleton(net);
        let block = block_with_proof(&tmpl, prev_hash, height, proof, 0, 5_000);

        // n=100 eligible (frozen window hi = 2-2 = 0) => not selected at round 0 => reject.
        let mut cs = base_chain();
        cs.proposer_registry.register(vrf_key, miner_pkh, 0);
        for i in 0..99u32 {
            let mut dk = [0u8; 33];
            dk[0] = 0x02;
            dk[1..5].copy_from_slice(&i.to_le_bytes());
            cs.proposer_registry.register(dk, [i as u8; 20], 0);
        }
        assert_eq!(cs.proposer_registry.eligible_count(height), 100);
        let err = cs
            .validate_block_proposer(&block, height, None)
            .expect_err("non-selected proposer must be rejected");
        assert!(err.contains("not selected"), "got: {err}");

        // Same block, same PoW, sole eligible key (n=1) => selected => accepted.
        let proof2 = prove(&secret, net, height, seed);
        let block2 = block_with_proof(&tmpl, prev_hash, height, proof2, 0, 5_000);
        let mut cs1 = base_chain();
        cs1.proposer_registry.register(vrf_key, miner_pkh, 0);
        assert_eq!(cs1.proposer_registry.eligible_count(height), 1);
        cs1.validate_block_proposer(&block2, height, None)
            .expect("sole eligible winner accepted regardless of PoW");
        std::env::remove_var("IRIUM_POAWX_PROPOSER_FREEZE_DEPTH");
        std::env::remove_var("IRIUM_NETWORK");
    }

    // ---- Track 1C / C1: gated floor-target HEADER ADMISSION -------------------
    //
    // add_header holds a header only, so it cannot evaluate a proposer assignment
    // and cannot replicate validate_block_header's precision. C1 therefore admits
    // against a CONSTANT floor when demotion is possible at the height, deferring
    // the real verdict to connect_block. These tests pin both directions of the
    // gate and prove the gate-off path is unchanged.

    const C1_HARD_BITS: u32 = 0x1d00ffff;

    /// Fresh chain whose genesis carries a hard (mainnet-level) target, so
    /// target_for_height(1) is genuinely unreachable by a CPU-ground header.
    fn c1_hard_chain() -> ChainState {
        let locked = crate::genesis::load_locked_genesis().expect("locked genesis");
        let mut genesis = block_from_locked(&locked).expect("genesis block");
        genesis.header.bits = C1_HARD_BITS;
        let pow_limit = Target {
            bits: C1_HARD_BITS,
        };
        let params = ChainParams {
            genesis_block: genesis,
            pow_limit,
            htlcv1_activation_height: None,
            mpsov1_activation_height: None,
            lwma: crate::chain::LwmaParams::new(None, pow_limit),
            lwma_v2: None,
            auxpow_activation_height: None,
            btc_spv: None,
            ltc_spv: None,
            htlc_btc_swap_v1_activation_height: None,
            btc_swap_bech32_payment_activation_height: None,
            htlc_ltc_swap_v1_activation_height: None,
            swap_order_v1_activation_height: None,
            ltc_swap_order_v1_activation_height: None,
            coinbase_header_batch_activation_height: None,
        };
        ChainState::new(params)
    }

    /// Header at height 1 off `chain`'s tip. `demoted == true` grinds to the 8-bit
    /// anti-spam floor while deliberately FAILING the hard declared target (the PoW
    /// profile of a demoted block); `false` grinds to a hash meeting neither.
    fn c1_header(chain: &ChainState, demoted: bool) -> BlockHeader {
        let mut hdr = BlockHeader {
            version: 1,
            prev_hash: chain.tip_hash(),
            merkle_root: [7u8; 32],
            time: 1_900_000_100,
            bits: C1_HARD_BITS,
            nonce: 0,
        };
        let floor = crate::pow::floor_target(8);
        let declared = Target {
            bits: C1_HARD_BITS,
        };
        loop {
            let h = hdr.hash_for_height(1);
            let meets_floor = meets_target(&h, floor.clone());
            let meets_declared = meets_target(&h, declared.clone());
            // A hard-target hit is astronomically unlikely, but assert rather than
            // assume: a header meeting the declared target would make the demoted
            // case vacuous.
            if demoted && meets_floor && !meets_declared {
                return hdr;
            }
            if !demoted && !meets_floor {
                return hdr;
            }
            hdr.nonce = hdr.nonce.wrapping_add(1);
        }
    }

    fn c1_env_on() {
        std::env::set_var("IRIUM_NETWORK", "testnet");
        std::env::set_var("IRIUM_POAWX_PROPOSER_ANTISPAM_BITS", "8");
        std::env::set_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT", "1");
    }
    fn c1_env_off() {
        std::env::set_var("IRIUM_NETWORK", "testnet");
        std::env::set_var("IRIUM_POAWX_PROPOSER_ANTISPAM_BITS", "8");
        std::env::remove_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT");
    }
    fn c1_env_clear() {
        std::env::remove_var("IRIUM_NETWORK");
        std::env::remove_var("IRIUM_POAWX_PROPOSER_ANTISPAM_BITS");
        std::env::remove_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT");
    }

    /// (1) Demotion ACTIVE => a floor-only header is ADMITTED.
    #[test]
    fn c1_add_header_admits_demoted_header_when_gate_on() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c1_env_on();
        let mut chain = c1_hard_chain();
        let hdr = c1_header(&chain, true);
        let hash = hdr.hash_for_height(1);
        assert!(
            !meets_target(
                &hash,
                Target {
                    bits: C1_HARD_BITS
                }
            ),
            "precondition: header must FAIL the declared target"
        );
        let got = chain.add_header(hdr);
        c1_env_clear();
        assert_eq!(
            got,
            Ok(1),
            "C1: floor-only header must be admitted while demotion is possible"
        );
    }

    /// (2) Demotion INACTIVE => the identical header is REJECTED (legacy behaviour
    /// preserved byte-for-byte; this is the mainnet path, where the activation
    /// const is None).
    #[test]
    fn c1_add_header_rejects_demoted_header_when_gate_off() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c1_env_on();
        let chain_probe = c1_hard_chain();
        let hdr = c1_header(&chain_probe, true);
        c1_env_off();
        let mut chain = c1_hard_chain();
        let got = chain.add_header(hdr);
        c1_env_clear();
        assert_eq!(
            got,
            Err("header does not meet target".to_string()),
            "gate off => declared target enforced, exactly as before C1"
        );
    }

    /// (3) A header meeting NEITHER floor nor declared target is rejected in BOTH
    /// modes. Admission is a lowered bar, not a removed one.
    #[test]
    fn c1_add_header_rejects_sub_floor_header_in_both_modes() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c1_env_on();
        let probe = c1_hard_chain();
        let hdr = c1_header(&probe, false);
        assert!(
            !meets_target(&hdr.hash_for_height(1), crate::pow::floor_target(8)),
            "precondition: header must fail even the anti-spam floor"
        );

        let mut chain_on = c1_hard_chain();
        let on = chain_on.add_header(hdr.clone());
        c1_env_off();
        let mut chain_off = c1_hard_chain();
        let off = chain_off.add_header(hdr);
        c1_env_clear();

        assert_eq!(
            on,
            Err("header does not meet target".to_string()),
            "gate on must still reject a header below the floor"
        );
        assert_eq!(
            off,
            Err("header does not meet target".to_string()),
            "gate off must reject it too"
        );
    }

    /// The shared helper itself: gate off returns the declared target verbatim, so
    /// every caller is byte-identical to legacy; gate on returns the constant floor.
    #[test]
    fn c1_header_admission_target_resolves_by_gate() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        let declared = Target {
            bits: C1_HARD_BITS,
        };
        c1_env_off();
        assert_eq!(
            crate::poawx_proposer::header_admission_target(declared.clone(), 1).bits,
            declared.bits,
            "gate off => declared target unchanged"
        );
        c1_env_on();
        let admitted = crate::poawx_proposer::header_admission_target(declared.clone(), 1);
        c1_env_clear();
        assert_eq!(
            admitted.to_target(),
            crate::pow::floor_target(8).to_target(),
            "gate on => constant anti-spam floor"
        );
    }

    // ---- Track 1C / C3: demotion-aware PoW in process_block -------------------
    //
    // Unlike C1 (header only) and C2 (stateless free fn), process_block holds the
    // full body AND &mut self, so it reuses validate_block_header's body-aware
    // idiom verbatim. The fixtures below deliberately place the block's parent in
    // block_store WITHOUT making it the active tip, so every test runs the FORK
    // path -- which is where wiring `previous` to self.chain.last() would silently
    // corrupt the VRF seed and parent_time.
    //
    // Assertions are on whether the PoW gate rejected, not on full acceptance:
    // C3 changes only the PoW gate, and a block can still fail later validators
    // that C3 does not touch. Claiming "accepted" would over-state the change.

    const C3_HARD_BITS: u32 = 0x1d00ffff;
    const C3_H: u64 = 2;
    const C3_POW_ERR: &str = "block does not satisfy proof-of-work target";

    fn c3_env_on(on: bool) {
        std::env::set_var("IRIUM_NETWORK", "testnet");
        std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT", "1");
        std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_REQUIRED", "1");
        std::env::set_var("IRIUM_POAWX_PROPOSER_ANTISPAM_BITS", "8");
        std::env::set_var("IRIUM_POAWX_PROPOSER_FREEZE_DEPTH", "2");
        if on {
            std::env::set_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT", "1");
        } else {
            std::env::remove_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT");
        }
    }
    fn c3_env_clear() {
        for k in [
            "IRIUM_NETWORK",
            "IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT",
            "IRIUM_POAWX_PROPOSER_VRF_REQUIRED",
            "IRIUM_POAWX_PROPOSER_ANTISPAM_BITS",
            "IRIUM_POAWX_PROPOSER_FREEZE_DEPTH",
            "IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT",
        ] {
            std::env::remove_var(k);
        }
    }

    /// Chain whose active tip is genesis, plus a height-1 parent living ONLY in
    /// block_store. So tip != parent: the fork path, and the exact shape in which
    /// `self.chain.last()` and the real parent diverge.
    fn c3_chain_with_detached_parent() -> (ChainState, Block, [u8; 32]) {
        let locked = crate::genesis::load_locked_genesis().expect("locked genesis");
        let mut genesis = block_from_locked(&locked).expect("genesis block");
        genesis.header.bits = C3_HARD_BITS;
        let pow_limit = Target {
            bits: C3_HARD_BITS,
        };
        let params = ChainParams {
            genesis_block: genesis.clone(),
            pow_limit,
            htlcv1_activation_height: None,
            mpsov1_activation_height: None,
            lwma: LwmaParams::new(None, pow_limit),
            lwma_v2: None,
            auxpow_activation_height: None,
            btc_spv: None,
            ltc_spv: None,
            htlc_btc_swap_v1_activation_height: None,
            btc_swap_bech32_payment_activation_height: None,
            htlc_ltc_swap_v1_activation_height: None,
            swap_order_v1_activation_height: None,
            ltc_swap_order_v1_activation_height: None,
            coinbase_header_batch_activation_height: None,
        };
        let mut chain = ChainState::new(params);

        let mut parent = genesis.clone();
        parent.header.prev_hash = genesis.header.hash_for_height(0);
        parent.header.time = genesis.header.time + 1;
        let parent_hash = parent.header.hash_for_height(1);
        chain.block_store.insert(parent_hash, parent.clone());
        chain.heights.insert(parent_hash, 1);
        chain.cumulative_work.insert(parent_hash, BigUint::zero());
        assert_ne!(
            parent_hash,
            chain.tip_hash(),
            "fixture invariant: parent must NOT be the active tip, or the test cannot \
             distinguish block_store.get(parent) from chain.last()"
        );
        (chain, parent, parent_hash)
    }

    /// Demoted proposer block at height 2 off `parent_hash`. `seed_from` selects the
    /// block used to derive the VRF epoch seed: the real parent (correct) or some
    /// other block (what a `self.chain.last()` wiring would effectively produce).
    fn c3_demoted_block(
        chain: &mut ChainState,
        parent_hash: [u8; 32],
        seed_from: Option<&Block>,
        register: bool,
    ) -> Block {
        let net = crate::activation::network_id_byte();
        let secret = secret_n(1);
        let seed = expected_epoch_seed(C3_H, parent_hash, seed_from);
        let proof = prove(&secret, net, C3_H, seed);
        let vrf_key = proof.assignment_public_key;
        let miner_pkh = proof.solver_pkh;
        if register {
            chain.proposer_registry.register(vrf_key, miner_pkh, 0);
            assert_eq!(chain.proposer_registry.eligible_count(C3_H), 1);
        }
        let ctx = ProposerCtx {
            assignment: ProposerAssignmentV1 { round: 0, proof },
        };
        let dom = PersistentDominance::from_env();
        let built = build_solo_poawx_block_with_proposer(
            &secret,
            net,
            C3_H,
            parent_hash,
            None,
            C3_HARD_BITS,
            1_900_000_300,
            1,
            ([0u8; 32], [0u8; 32]),
            &dom,
            None,
            Some(&ctx),
            None,
        )
        .expect("build demoted proposer block");
        built.block
    }

    fn c3_rejected_for_pow(r: &Result<(u64, [u8; 32]), String>) -> bool {
        matches!(r, Err(e) if e == C3_POW_ERR)
    }

    /// (1) Demotion ACTIVE + valid selected assignment => the PoW gate does NOT
    /// reject a floor-only block.
    #[test]
    fn c3_process_block_accepts_demoted_when_gate_on() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c3_env_on(true);
        let (mut chain, parent, parent_hash) = c3_chain_with_detached_parent();
        let block = c3_demoted_block(&mut chain, parent_hash, Some(&parent), true);
        let hash = block.header.hash_for_height(C3_H);
        assert!(
            !meets_target(
                &hash,
                Target {
                    bits: C3_HARD_BITS
                }
            ),
            "precondition: block must FAIL the declared target, else demotion is not \
             what is being tested"
        );
        let got = chain.process_block(block);
        c3_env_clear();
        assert!(
            !c3_rejected_for_pow(&got),
            "C3: demoted block must clear process_block's PoW gate; got {:?}",
            got
        );
    }

    /// (2) Demotion INACTIVE => the identical block is rejected on PoW. Legacy
    /// behaviour, which is the mainnet path (activation const is None).
    #[test]
    fn c3_process_block_rejects_demoted_when_gate_off() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c3_env_on(true);
        let (mut chain, parent, parent_hash) = c3_chain_with_detached_parent();
        let block = c3_demoted_block(&mut chain, parent_hash, Some(&parent), true);
        c3_env_on(false);
        let got = chain.process_block(block);
        c3_env_clear();
        assert!(
            c3_rejected_for_pow(&got),
            "gate off => full target enforced, exactly as before C3; got {:?}",
            got
        );
    }

    /// (3) A block BELOW the anti-spam floor is rejected in BOTH modes, even with a
    /// valid selected assignment. Demotion lowers the bar to the floor; it does not
    /// remove it. Built as a genuine demoted block, then its nonce is tampered so the
    /// hash falls under the floor -- the nonce does not affect the assignment, which
    /// lives in the receipts, so this isolates the PoW gate.
    #[test]
    fn c3_process_block_rejects_sub_floor_block_in_both_modes() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        let floor = crate::pow::floor_target(8);

        c3_env_on(true);
        let (mut chain_on, parent_on, ph_on) = c3_chain_with_detached_parent();
        let mut block_on = c3_demoted_block(&mut chain_on, ph_on, Some(&parent_on), true);
        while meets_target(&block_on.header.hash_for_height(C3_H), floor) {
            block_on.header.nonce = block_on.header.nonce.wrapping_add(1);
        }
        assert!(
            !meets_target(&block_on.header.hash_for_height(C3_H), floor),
            "precondition: block must fail even the anti-spam floor"
        );
        let on = chain_on.process_block(block_on);

        let (mut chain_off, parent_off, ph_off) = c3_chain_with_detached_parent();
        let mut block_off = c3_demoted_block(&mut chain_off, ph_off, Some(&parent_off), true);
        while meets_target(&block_off.header.hash_for_height(C3_H), floor) {
            block_off.header.nonce = block_off.header.nonce.wrapping_add(1);
        }
        c3_env_on(false);
        let off = chain_off.process_block(block_off);
        c3_env_clear();

        assert!(
            c3_rejected_for_pow(&on),
            "gate on must still reject a block below the floor; got {:?}",
            on
        );
        assert!(
            c3_rejected_for_pow(&off),
            "gate off must reject it too; got {:?}",
            off
        );
    }

    /// (4) THE FORK TEST. process_block must derive `previous` from the block's real
    /// parent (block_store), not from the active tip. Both blocks below are built at
    /// the same height off the same parent hash and differ ONLY in which block seeded
    /// the VRF proof. The parent-seeded one must clear the PoW gate; the tip-seeded
    /// one must not. If `previous` were ever wired to self.chain.last(), this test
    /// inverts -- which is precisely the silent-demotion-failure this track exists to
    /// catch.
    #[test]
    fn c3_process_block_uses_real_parent_not_tip_for_previous() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c3_env_on(true);

        let (mut chain_a, parent, parent_hash) = c3_chain_with_detached_parent();
        let tip_block = chain_a.chain.last().cloned().expect("genesis tip");
        assert_ne!(
            tip_block.header.hash_for_height(0),
            parent_hash,
            "fixture invariant: tip and parent must differ"
        );
        let seeded_by_parent = c3_demoted_block(&mut chain_a, parent_hash, Some(&parent), true);
        let got_parent = chain_a.process_block(seeded_by_parent);

        let (mut chain_b, _p, ph_b) = c3_chain_with_detached_parent();
        let seeded_by_tip = c3_demoted_block(&mut chain_b, ph_b, Some(&tip_block), true);
        let got_tip = chain_b.process_block(seeded_by_tip);
        c3_env_clear();

        assert!(
            !c3_rejected_for_pow(&got_parent),
            "block seeded from the REAL parent must clear the PoW gate; got {:?}",
            got_parent
        );
        assert!(
            c3_rejected_for_pow(&got_tip),
            "block seeded from the TIP must be rejected -- if this passes, previous is \
             wired to chain.last() and demotion is silently applying to the wrong \
             seed; got {:?}",
            got_tip
        );
    }

    // ---- Track 1C / C4: block-first selection ---------------------------------
    //
    // After C6 a demoted chain banks floor work, so it can never out-weigh a PoW
    // chain. These fixtures reproduce that shape: a candidate whose cumulative work
    // is BELOW our total_work, which work-based selection rejects by construction
    // and block-first selection must still fetch.

    /// C4 env: activation at height 0, because these fixtures have a genesis-only
    /// chain (tip_height == 0) and the gate is keyed on TIP height, mirroring how
    /// fork_choice_hardening_active is used. With activation at 1 the gate is
    /// correctly OFF at tip 0 -- which is right, and is what the first run caught.
    fn c4_env_on(on: bool) {
        std::env::set_var("IRIUM_NETWORK", "testnet");
        std::env::set_var("IRIUM_POAWX_PROPOSER_ANTISPAM_BITS", "8");
        std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT", "0");
        std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_REQUIRED", "1");
        if on {
            std::env::set_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT", "0");
        } else {
            std::env::remove_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT");
        }
    }
    fn c4_env_clear() {
        c3_env_clear();
        std::env::remove_var("IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT");
        std::env::remove_var("IRIUM_POAWX_PROPOSER_VRF_REQUIRED");
    }

    /// Chain with an inflated total_work, plus one header at `height` carrying
    /// `work` far below it. `linked` controls whether the header's parent is known,
    /// which is what the adoptability floor filter keys on.
    fn c4_chain(work_below: bool, linked: bool) -> (ChainState, [u8; 32]) {
        let mut chain = c1_hard_chain();
        let genesis_hash = chain.chain[0].header.hash_for_height(0);
        // Our chain looks very heavy: the demoted candidate cannot compete on work.
        if work_below {
            chain.total_work = BigUint::from(1u64) << 200;
        } else {
            chain.total_work = BigUint::zero();
        }
        let mut hdr = BlockHeader {
            version: 1,
            prev_hash: if linked { genesis_hash } else { [42u8; 32] },
            merkle_root: [21u8; 32],
            time: 1_900_000_600,
            bits: C1_HARD_BITS,
            nonce: 7,
        };
        hdr.nonce = 7;
        let hash = hdr.hash_for_height(1);
        chain.headers.insert(
            hash,
            HeaderWork {
                header: hdr,
                height: 1,
                work: BigUint::from(1u64) << 8, // floor-shaped, tiny
            },
        );
        (chain, hash)
    }

    /// (1) Under the gate, a candidate that work-based selection rejects (its work
    /// is below our total_work) IS selected for fetch.
    #[test]
    fn c4_selects_demoted_candidate_under_gate() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c4_env_on(true);
        let (chain, hash) = c4_chain(true, true);
        assert!(
            crate::poawx_proposer::block_first_selection_active(chain.height.saturating_sub(1)),
            "precondition: block-first must be active"
        );
        let got = chain.best_header_if_better();
        c4_env_clear();
        let got = got.expect("block-first must return a candidate work-based selection drops");
        assert_eq!(got.header.hash_for_height(got.height), hash);
    }

    /// (2) Gate off => the legacy work comparison, byte-identical. The same
    /// candidate is correctly NOT selected, because its work is below our tip's.
    #[test]
    fn c4_gate_off_is_work_based_and_unchanged() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c4_env_on(false);
        let (chain, _hash) = c4_chain(true, true);
        let got = chain.best_header_if_better();
        c4_env_clear();
        assert!(
            got.is_none(),
            "gate off must keep the legacy hw.work > total_work rule, which rejects \
             this candidate; got {:?}",
            got.map(|h| h.height)
        );
    }

    /// (3) The GAP A adoptability floor must survive block-first selection: an
    /// unlinked candidate (no known fork ancestor) is fetched by the unfiltered
    /// selector but NOT by the adoptable one.
    #[test]
    fn c4_adoptability_floor_preserved_under_gate() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c4_env_on(true);
        let (chain, _hash) = c4_chain(true, false); // unlinked parent
        let unfiltered = chain.best_header_if_better();
        let adoptable = chain.best_adoptable_header_if_better();
        c4_env_clear();
        assert!(
            unfiltered.is_some(),
            "unfiltered selector should still offer the candidate"
        );
        assert!(
            adoptable.is_none(),
            "adoptable selector must drop a candidate with no reachable fork \
             ancestor -- chasing it would be the GAP A sync hijack"
        );
    }

    /// (4) THE LIVELOCK GUARD. The selector's gate must never be true where the
    /// ADOPTER's gate is false. process_block's do_reorg branch switches on
    /// proposer_vrf_enforced; if block-first activated on demotion alone, the
    /// demotion-on / VRF-off configuration would chase chains it then refuses to
    /// adopt -- silent, and after C6 permanent, since a demoted chain never wins on
    /// work.
    #[test]
    fn c4_selector_gate_never_outruns_adopter_gate() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        for (demotion, vrf) in [(true, true), (true, false), (false, true), (false, false)] {
            std::env::set_var("IRIUM_NETWORK", "testnet");
            if demotion {
                std::env::set_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT", "1");
            } else {
                std::env::remove_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT");
            }
            if vrf {
                std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT", "1");
                std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_REQUIRED", "1");
            } else {
                std::env::remove_var("IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT");
                std::env::remove_var("IRIUM_POAWX_PROPOSER_VRF_REQUIRED");
            }
            let selector = crate::poawx_proposer::block_first_selection_active(1);
            let adopter = crate::poawx_proposer::proposer_vrf_enforced(1);
            assert!(
                !selector || adopter,
                "selector active while adopter is work-based (demotion={} vrf={}) => \
                 sync livelock",
                demotion,
                vrf
            );
        }
        c3_env_clear();
        std::env::remove_var("IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT");
        std::env::remove_var("IRIUM_POAWX_PROPOSER_VRF_REQUIRED");
    }

    // ---- Track 1C / C6: demonstrated-work accounting --------------------------
    //
    // Work is credited from the target the block actually DEMONSTRATED, never from
    // its declared bits. Test (2) is the load-bearing one: it is the regression that
    // proves the tempting gate-based rule ("demotion active => credit the floor")
    // wrong, since that rule would under-credit every honest full-PoW block at a
    // demotion-active height by the same ~2^35 it was meant to remove.

    fn c6_floor_work() -> BigUint {
        ChainState::work_for_target(crate::pow::floor_target(8))
    }
    fn c6_declared_work() -> BigUint {
        ChainState::work_for_target(Target {
            bits: C3_HARD_BITS,
        })
    }

    /// (1) A demoted block (meets only the floor) is credited FLOOR work.
    #[test]
    fn c6_demoted_block_credited_floor_work() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c3_env_on(true);
        let (mut chain, parent, ph) = c3_chain_with_detached_parent();
        let block = c3_demoted_block(&mut chain, ph, Some(&parent), true);
        let got = chain.block_work(&block, C3_H);
        c3_env_clear();
        assert_eq!(
            got,
            c6_floor_work(),
            "demoted block must bank floor work, not its declared ~2^35 over-statement"
        );
        assert_ne!(got, c6_declared_work(), "must not bank declared work");
    }

    /// (2) THE REGRESSION TEST. An HONEST full-PoW block at a demotion-active height
    /// is still credited its full DECLARED work. A gate-based rule would credit it
    /// the floor and under-count real work by ~2^35 -- worse than the bug C6 fixes.
    #[test]
    fn c6_honest_full_pow_block_still_credited_declared_work() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c3_env_on(true);
        let (chain, _parent, ph) = c3_chain_with_detached_parent();
        assert!(
            crate::poawx_proposer::pow_demotion_active(C3_H),
            "precondition: demotion must be ACTIVE, else this proves nothing"
        );
        // Easy declared bits, ground to genuinely meet them: an honest miner who did
        // the full work for the target it declares.
        let mut header = BlockHeader {
            version: 1,
            prev_hash: ph,
            merkle_root: [11u8; 32],
            time: 1_900_000_400,
            bits: 0x207f_ffff,
            nonce: 0,
        };
        let declared = header.target();
        while !meets_target(&header.hash_for_height(C3_H), declared) {
            header.nonce = header.nonce.wrapping_add(1);
        }
        let got = ChainState::work_for_target(chain.demonstrated_work_target(&header, C3_H));
        c3_env_clear();
        assert_eq!(
            got,
            ChainState::work_for_target(declared),
            "an honest full-PoW block must keep its full declared work even while \
             demotion is active -- crediting the floor here would be the gate-based \
             bug"
        );
    }

    /// (3) An AuxPoW block is credited DECLARED work. Its own header hash does not
    /// meet the declared target -- satisfaction comes from the merged-mining chain --
    /// so the naive demonstrated-work rule would under-credit every merged-mined
    /// block. "What we credit" must match "why we accepted".
    #[test]
    fn c6_auxpow_block_credited_declared_work() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c3_env_on(true);
        let (mut chain, _parent, ph) = c3_chain_with_detached_parent();
        chain.params.auxpow_activation_height = Some(1);
        let mut header = BlockHeader {
            version: 1 | crate::auxpow::AUXPOW_VERSION_BIT,
            prev_hash: ph,
            merkle_root: [12u8; 32],
            time: 1_900_000_500,
            bits: C3_HARD_BITS,
            nonce: 0,
        };
        // Deliberately NOT ground: its own hash misses the hard declared target,
        // exactly like a real merged-mined block.
        while meets_target(&header.hash_for_height(C3_H), header.target()) {
            header.nonce = header.nonce.wrapping_add(1);
        }
        let got = ChainState::work_for_target(chain.demonstrated_work_target(&header, C3_H));
        c3_env_clear();
        assert_eq!(
            got,
            c6_declared_work(),
            "AuxPoW block must bank declared work; crediting the floor would gut \
             merged mining"
        );
    }

    /// (4) Gate OFF => declared work always, byte-identical to pre-C6. This is the
    /// mainnet configuration (activation const is None).
    #[test]
    fn c6_gate_off_credits_declared_work() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c3_env_on(true);
        let (mut chain, parent, ph) = c3_chain_with_detached_parent();
        let block = c3_demoted_block(&mut chain, ph, Some(&parent), true);
        c3_env_on(false);
        let got = chain.block_work(&block, C3_H);
        c3_env_clear();
        assert_eq!(
            got,
            c6_declared_work(),
            "gate off => declared work, exactly as before C6"
        );
    }

    /// (5) SYMMETRY. Accumulation and subtraction must credit the SAME value for the
    /// same block, or total_work drifts permanently across any reorg spanning a
    /// demoted block -- and the drift survives restart. connect_block credits at
    /// `expected_height`; disconnect_tip_block debits at `self.height - 1`. This pins
    /// that those are the same height, and that both route through block_work, for a
    /// demoted block where the two formulas would differ by ~2^35.
    #[test]
    fn c6_connect_and_disconnect_credit_identical_work() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        c3_env_on(true);
        let (mut chain, parent, ph) = c3_chain_with_detached_parent();
        let block = c3_demoted_block(&mut chain, ph, Some(&parent), true);

        // connect_block credits block_work(&block, expected_height) where
        // expected_height == self.height at the time of the call.
        let credited = chain.block_work(&block, C3_H);
        // disconnect_tip_block debits block_work(&tip_block, self.height - 1). Model
        // the post-connect state: height would be C3_H + 1, so tip_height == C3_H.
        let debited = chain.block_work(&block, (C3_H + 1).saturating_sub(1));
        c3_env_clear();

        assert_eq!(
            credited, debited,
            "accumulation and subtraction must agree, or total_work drifts on reorg"
        );
        assert_eq!(
            credited,
            c6_floor_work(),
            "and both must be the floor-derived value for a demoted block, not the \
             declared one -- if this is declared work the symmetry is vacuous"
        );
    }

    /// CLAUDE.md §12: the spacing floor's mainnet branch reads a COMPILED const and
    /// IGNORES the env, so only a `network_id == 0` block validation can prove it. The
    /// rest of the suite runs at `network_id != 0` and would exercise the env branch
    /// instead — green there says nothing about production. This drives the real
    /// `validate_block_header` (the exact check `connect_block` runs) in a mainnet
    /// context, in all three directions: reject too-early, admit properly-spaced, and
    /// inert below the activation height.
    #[test]
    fn min_block_spacing_mainnet_context_rejects_early_admits_spaced_inert_below() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        std::env::set_var("IRIUM_NETWORK", "mainnet");
        assert_eq!(
            crate::activation::network_id_byte(),
            0,
            "this test is vacuous anywhere but a mainnet context"
        );

        let armed = crate::poawx_proposer::MAINNET_MIN_BLOCK_SPACING_ACTIVATION_HEIGHT
            .expect("the spacing floor must be armed for this test to mean anything");
        let spacing = crate::poawx_proposer::min_block_spacing_secs();
        assert_eq!(
            spacing,
            crate::constants::BLOCK_TARGET_INTERVAL_V2,
            "mainnet spacing is the protocol block-time target, not a separate number"
        );
        // The env must be powerless on mainnet — otherwise an operator could relax
        // consensus with a variable, which is the class of bug that armed an unproven
        // validator on 2026-07-23.
        std::env::set_var("IRIUM_POAWX_MIN_BLOCK_SPACING_ACTIVATION_HEIGHT", "999999999");
        assert!(
            crate::poawx_proposer::min_block_spacing_active(armed),
            "mainnet must ignore the env override and use the compiled height"
        );
        std::env::remove_var("IRIUM_POAWX_MIN_BLOCK_SPACING_ACTIVATION_HEIGHT");

        const HARD_BITS: u32 = 0x1d00ffff;
        let locked = crate::genesis::load_locked_genesis().expect("locked genesis");
        let mut parent = block_from_locked(&locked).expect("genesis block");
        parent.header.bits = HARD_BITS;
        let pow_limit = Target { bits: HARD_BITS };
        let params = ChainParams {
            genesis_block: parent.clone(),
            pow_limit,
            htlcv1_activation_height: None,
            mpsov1_activation_height: None,
            lwma: LwmaParams::new(None, pow_limit),
            lwma_v2: None,
            auxpow_activation_height: None,
            btc_spv: None,
            ltc_spv: None,
            htlc_btc_swap_v1_activation_height: None,
            btc_swap_bech32_payment_activation_height: None,
            htlc_ltc_swap_v1_activation_height: None,
            swap_order_v1_activation_height: None,
            ltc_swap_order_v1_activation_height: None,
            coinbase_header_batch_activation_height: None,
        };
        let chain = ChainState::new(params);
        let parent_time = parent.header.time;

        // (1) REJECT: the spacing actually observed live on mainnet — a 9s gap, which
        // was the mean for 65% of blocks and the reason emission ran 2.48x hot.
        let mut early = parent.clone();
        early.header.prev_hash = parent.header.hash_for_height(armed.saturating_sub(1));
        early.header.time = parent_time + 9;
        let err = chain
            .validate_block_header(&early, armed, Some(&parent))
            .expect_err("a 9s-spaced block must be rejected at the activation height");
        assert!(
            err.contains("block too early"),
            "expected the spacing rejection, got: {err}"
        );

        // (2) ADMIT: the same block spaced at the floor clears the gate. It may still
        // fail a LATER check (merkle/PoW) — the point is that it is no longer rejected
        // FOR SPACING, which is what distinguishes a working gate from one that rejects
        // everything. That distinction is exactly what the 2026-07-23 halt lacked.
        let mut spaced = early.clone();
        spaced.header.time = parent_time + spacing as u32;
        if let Err(e) = chain.validate_block_header(&spaced, armed, Some(&parent)) {
            assert!(
                !e.contains("block too early"),
                "a properly-spaced block must not be rejected for spacing; got: {e}"
            );
        }

        // (3) INERT BELOW: one height under the activation the floor does not exist, so
        // the same 9s block is not rejected for spacing. This is what keeps every
        // already-persisted mainnet block valid on restart — a retroactive activation
        // would make each node reject its own chain.
        let below = armed - 1;
        let mut legacy = early.clone();
        legacy.header.prev_hash = parent.header.hash_for_height(below.saturating_sub(1));
        if let Err(e) = chain.validate_block_header(&legacy, below, Some(&parent)) {
            assert!(
                !e.contains("block too early"),
                "below the activation the floor must not apply; got: {e}"
            );
        }
    }

    #[test]
    fn pow_demotion_accepts_floor_block_only_with_valid_assignment() {
        let _env = crate::test_env::guard();
        // Part-1/Part-2 PoW demotion, proven at the consensus PoW gate
        // `validate_block_header` (the exact check `connect_block` runs). A validly
        // SELECTED proposer's block is ACCEPTED while its header hash meets only the
        // CPU-reachable anti-spam floor against a HARD (mainnet-level) network target
        // it could never satisfy. The IDENTICAL block with its proposer assignment
        // stripped is REJECTED, still requiring the full target. Hashrate never
        // decides the verdict; a valid selected assignment does.
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        // testnet net-id: the devnet/regtest fast-mining target override (which pins
        // the target to 0x207fffff) does NOT apply, so a hard-bits genesis yields a
        // hard target_for_height(1). The proposer-VRF gate is env-driven off mainnet,
        // so it can be enforced here.
        std::env::set_var("IRIUM_NETWORK", "testnet");
        std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT", "1");
        std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_REQUIRED", "1");
        std::env::set_var("IRIUM_POAWX_PROPOSER_ANTISPAM_BITS", "8");
        // Explicit demotion gate ON (testnet). Without this, demotion is off and the
        // full network target is enforced (see the gate-off assertion at the end).
        std::env::set_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT", "1");
        // Freeze depth 2 (the minimum): a height-0 registration falls in the frozen
        // window [0,0] for target height 2, so it is eligible.
        std::env::set_var("IRIUM_POAWX_PROPOSER_FREEZE_DEPTH", "2");
        let net = crate::activation::network_id_byte();
        assert!(
            crate::poawx_proposer::proposer_vrf_enforced(1),
            "proposer VRF must be enforced for this test"
        );

        // Hard, mainnet-level network target the CPU-built block will NOT meet.
        const HARD_BITS: u32 = 0x1d00ffff;

        // Chain whose genesis carries the hard bits: with no devnet override on
        // testnet, target_for_height(1) resolves to the genesis target = HARD_BITS.
        let locked = crate::genesis::load_locked_genesis().expect("locked genesis");
        let mut genesis = block_from_locked(&locked).expect("genesis block");
        genesis.header.bits = HARD_BITS;
        let pow_limit = Target { bits: HARD_BITS };
        let params = ChainParams {
            genesis_block: genesis.clone(),
            pow_limit,
            htlcv1_activation_height: None,
            mpsov1_activation_height: None,
            lwma: LwmaParams::new(None, pow_limit),
            lwma_v2: None,
            auxpow_activation_height: None,
            btc_spv: None,
            ltc_spv: None,
            htlc_btc_swap_v1_activation_height: None,
            btc_swap_bech32_payment_activation_height: None,
            htlc_ltc_swap_v1_activation_height: None,
            swap_order_v1_activation_height: None,
            ltc_swap_order_v1_activation_height: None,
            coinbase_header_batch_activation_height: None,
        };
        let mut chain = ChainState::new(params);
        // Proposer eligibility requires target_height >= freeze_depth (>= 2), so we
        // validate at HEIGHT 2. A genesis-only chain still yields the hard genesis
        // target at any height (LWMA sample count is 0), and we use previous=None
        // with a zero prev-hash exactly like the sibling
        // `non_selected_proposer_rejected_even_with_max_pow` test.
        const H: u64 = 2;
        let prev_hash = [0u8; 32];
        assert_eq!(
            chain.target_for_height(H).bits,
            HARD_BITS,
            "network target at height 2 is the hard mainnet-level target"
        );

        // Build the proposer block at height H. It declares HARD_BITS, but the miner
        // grinds ONLY the anti-spam floor (Part-2 demotion inside the harness).
        let secret = secret_n(1);
        let seed = expected_epoch_seed(H, prev_hash, None);
        let proof = prove(&secret, net, H, seed);
        let vrf_key = proof.assignment_public_key;
        let miner_pkh = proof.solver_pkh;
        let ctx = ProposerCtx {
            assignment: ProposerAssignmentV1 { round: 0, proof },
        };
        let dom = PersistentDominance::from_env();
        let built = build_solo_poawx_block_with_proposer(
            &secret,
            net,
            H,
            prev_hash,
            None,
            HARD_BITS,
            genesis.header.time + 1,
            1,
            ([0u8; 32], [0u8; 32]),
            &dom,
            None,
            Some(&ctx),
            None,
        )
        .expect("build demoted proposer block");
        let block = built.block;

        // Sanity: the header hash meets the 8-bit floor but NOT the hard target, so the
        // ONLY reason the block can be valid is demotion (not hashrate).
        let hash = block.header.hash_for_height(H);
        assert!(
            crate::pow::meets_target(&hash, crate::pow::floor_target(8)),
            "CPU block meets the 8-bit anti-spam floor"
        );
        assert!(
            !crate::pow::meets_target(&hash, Target { bits: HARD_BITS }),
            "CPU block must NOT meet the mainnet-hard target"
        );

        // Register the proposer key so it is eligible (frozen window [0,0] at H=2) and
        // (sole key => n=1) selected.
        chain.proposer_registry.register(vrf_key, miner_pkh, 0);
        assert_eq!(chain.proposer_registry.eligible_count(H), 1);

        // (1) Valid selected assignment => demotion applies => PoW gate ACCEPTS.
        assert!(
            chain.proposer_demotion_applies(&block, H, None),
            "demotion applies for the validly-selected proposer"
        );
        chain
            .validate_block_header(&block, H, None)
            .expect("connect_block PoW gate accepts the demoted-floor proposer block");

        // (2) Identical block, assignment stripped => no demotion => full target => REJECT.
        let mut stripped = block.clone();
        {
            let receipts = stripped.poawx_receipts.as_mut().expect("receipts present");
            let ext = receipts[0].phase20_ext.as_mut().expect("phase20 ext present");
            ext.proposer_assignment = None;
        }
        assert!(
            !chain.proposer_demotion_applies(&stripped, H, None),
            "no valid assignment => no demotion"
        );
        let err = chain
            .validate_block_header(&stripped, H, None)
            .expect_err("without a valid assignment the full network target is required");
        assert!(
            err.contains("proof-of-work"),
            "expected full-target PoW rejection, got: {err}"
        );

        // (3) GATE OFF: unset the demotion gate. The SAME valid-selected-proposer block
        // (the one accepted in step 1) is now REJECTED -- the full network target is
        // enforced, i.e. no demotion behaviour is possible without the explicit gate.
        std::env::remove_var("IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT");
        assert!(
            !chain.proposer_demotion_applies(&block, H, None),
            "gate unset => demotion must not apply"
        );
        let err_off = chain
            .validate_block_header(&block, H, None)
            .expect_err("gate unset => full network target enforced");
        assert!(
            err_off.contains("proof-of-work"),
            "gate unset must enforce full PoW, got: {err_off}"
        );

        for k in [
            "IRIUM_POAWX_POW_DEMOTION_ACTIVATION_HEIGHT",
            "IRIUM_POAWX_PROPOSER_FREEZE_DEPTH",
            "IRIUM_POAWX_PROPOSER_ANTISPAM_BITS",
            "IRIUM_POAWX_PROPOSER_VRF_REQUIRED",
            "IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT",
            "IRIUM_NETWORK",
        ] {
            std::env::remove_var(k);
        }
    }

    #[test]
    fn multi_miner_cpu_vs_asic_integration() {
        let _env = crate::test_env::guard();
        // Several CPUs at round 0 plus an ASIC that only reaches round 1: the canonical
        // winner is always a round-0 CPU; the ASIC never wins, whatever its hashrate.
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        std::env::set_var("IRIUM_NETWORK", "devnet");
        let net = crate::activation::network_id_byte();
        let gh = genesis_block().header.hash_for_height(0);
        let seed = expected_epoch_seed(1, gh, Some(&genesis_block()));
        let cpus: Vec<Block> = (0..4u64)
            .map(|i| proposer_block_h1(&secret_n(i + 1), net, seed, 0))
            .collect();
        let asic = proposer_block_h1(&secret_n(99), net, seed, 1);
        let asic_rank = ChainState::block_proposer_rank(&asic);
        for c in &cpus {
            assert!(
                ChainState::block_proposer_rank(c) < asic_rank,
                "a round-0 CPU outranks the round-1 ASIC"
            );
        }
        let winner = cpus
            .iter()
            .chain(std::iter::once(&asic))
            .min_by_key(|b| ChainState::block_proposer_rank(b))
            .unwrap();
        assert_eq!(
            ChainState::block_proposer_rank(winner).0,
            0,
            "winner is a round-0 proposer (a CPU), never the ASIC"
        );
        std::env::remove_var("IRIUM_NETWORK");
    }

    fn set_reg_env() {
        std::env::set_var("IRIUM_NETWORK", "devnet");
        std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT", "1");
        std::env::set_var("IRIUM_POAWX_PROPOSER_VRF_REQUIRED", "1");
        std::env::set_var("IRIUM_POAWX_PROPOSER_REGISTRATION_ACTIVATION_HEIGHT", "1");
    }
    fn clear_reg_env() {
        for k in [
            "IRIUM_NETWORK",
            "IRIUM_POAWX_PROPOSER_VRF_ACTIVATION_HEIGHT",
            "IRIUM_POAWX_PROPOSER_VRF_REQUIRED",
            "IRIUM_POAWX_PROPOSER_REGISTRATION_ACTIVATION_HEIGHT",
        ] {
            std::env::remove_var(k);
        }
    }

    fn block_with_registrations(
        template: &PoawxBlockReceipt,
        prev_hash: [u8; 32],
        height: u64,
        announces: Vec<ProposerRegistrationV1>,
        activations: Vec<ProposerRegistrationV1>,
    ) -> Block {
        let mut r = template.clone();
        r.height = height;
        let mut ext = r.phase20_ext.clone().expect("ext");
        ext.proposer_registrations = Some(ProposerRegistrationSection {
            announces,
            activations,
        });
        r.phase20_ext = Some(ext);
        Block {
            header: BlockHeader {
                version: 0,
                prev_hash,
                merkle_root: [0u8; 32],
                time: 1_000,
                bits: 0x207fffff,
                nonce: 0,
            },
            transactions: vec![],
            auxpow: None,
            poawx_receipts: Some(vec![r]),
        }
    }

    #[test]
    fn registration_queue_apply_revert_symmetry() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        set_reg_env();
        let net = crate::activation::network_id_byte();
        let mut cs = base_chain();
        let anchor = cs.chain[0].header.hash_for_height(0);
        let tmpl = ext_skeleton(net);
        let ra = ProposerRegistrationV1::build_signed(&[0xA1u8; 32], net, 0, &anchor, 8).unwrap();
        let rb = ProposerRegistrationV1::build_signed(&[0xB2u8; 32], net, 0, &anchor, 8).unwrap();

        // height 1: announce ra + rb (queue empty => 0 activations).
        let b1 = block_with_registrations(&tmpl, anchor, 1, vec![ra.clone(), rb.clone()], vec![]);
        cs.chain.push(b1.clone());
        cs.apply_block_proposer_registrations(1);
        assert_eq!(cs.proposer_reg_queue.len(), 2);
        assert!(!cs.proposer_registry.is_eligible(&ra.vrf_pubkey, 1000)); // queued, not active

        // height 2: force-drain head (ra) => activated + registered.
        let b2 = block_with_registrations(&tmpl, anchor, 2, vec![], vec![ra.clone()]);
        cs.chain.push(b2.clone());
        cs.apply_block_proposer_registrations(2);
        assert_eq!(cs.proposer_reg_queue.len(), 1);
        assert_eq!(cs.proposer_reg_queue.front().unwrap().vrf_pubkey, rb.vrf_pubkey);
        assert!(cs.proposer_registry.is_eligible(&ra.vrf_pubkey, 1000)); // eligible past freeze

        // revert height 2 == exact inverse.
        cs.revert_block_proposer_registrations(&b2, 2);
        cs.chain.pop();
        assert_eq!(cs.proposer_reg_queue.len(), 2);
        assert_eq!(cs.proposer_reg_queue.front().unwrap().vrf_pubkey, ra.vrf_pubkey);
        assert!(!cs.proposer_registry.is_eligible(&ra.vrf_pubkey, 1000));

        // revert height 1 => empty.
        cs.revert_block_proposer_registrations(&b1, 1);
        cs.chain.pop();
        assert_eq!(cs.proposer_reg_queue.len(), 0);
        clear_reg_env();
    }

    #[test]
    fn part_b_eligible_count_proposer_only() {
        let _env = crate::test_env::guard();
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());
        set_reg_env();
        let net = crate::activation::network_id_byte();
        let gh = genesis_block().header.hash_for_height(0);
        let seed = expected_epoch_seed(1, gh, Some(&genesis_block()));
        // real all-gates block: 3 sub-role assignment keys + 1 proposer key.
        let bwp = proposer_block_h1(&secret_n(1), net, seed, 0);
        // legacy (registration inactive): sub-role (3) + proposer (1) = 4.
        assert_eq!(ChainState::proposer_keys_from_block(&bwp, false).len(), 4);
        // Part B (registration active): proposer key only = 1.
        assert_eq!(ChainState::proposer_keys_from_block(&bwp, true).len(), 1);
        clear_reg_env();
    }

